const std = @import("std");

pub const Error = error{
    InvalidArgument,
    SizeMismatch,
    NegativeEpsilon,
};

pub const Tensor = struct {
    data: []f32,

    pub fn len(self: Tensor) usize {
        return self.data.len;
    }
};

pub const RmsNormBackwardResult = struct {
    grad_input: []f32,
    grad_weight: []f32,
};

pub const LayerNormStats = struct {
    mean: f32,
    variance: f32,
    inv_std: f32,
};

fn checkEps(eps: f32) Error!void {
    if (eps < 0.0) return Error.NegativeEpsilon;
}

fn checkNormalizedShape(numel: usize, normalized_shape: usize) Error!usize {
    if (normalized_shape == 0) return Error.InvalidArgument;
    if (numel % normalized_shape != 0) return Error.SizeMismatch;
    return numel / normalized_shape;
}

fn checkedMul(a: usize, b: usize) Error!usize {
    return std.math.mul(usize, a, b) catch Error.InvalidArgument;
}

fn rowSlice(data: []const f32, row: usize, normalized_shape: usize) Error![]const f32 {
    const start = try checkedMul(row, normalized_shape);
    const end = start + normalized_shape;
    if (end > data.len) return Error.SizeMismatch;
    return data[start..end];
}

fn rowSliceMut(data: []f32, row: usize, normalized_shape: usize) Error![]f32 {
    const start = try checkedMul(row, normalized_shape);
    const end = start + normalized_shape;
    if (end > data.len) return Error.SizeMismatch;
    return data[start..end];
}

fn rmsMeanSquare(row: []const f32) f32 {
    var sum_sq: f64 = 0.0;
    for (row) |x| {
        const xd: f64 = x;
        sum_sq += xd * xd;
    }
    return @floatCast(sum_sq / @as(f64, @floatFromInt(row.len)));
}

fn rmsRsqrt(row: []const f32, eps: f32) f32 {
    const mean_sq = rmsMeanSquare(row);
    return 1.0 / @sqrt(mean_sq + eps);
}

fn layerNormStats(row: []const f32, eps: f32) LayerNormStats {
    var mean: f64 = 0.0;
    var m2: f64 = 0.0;
    var count: usize = 0;
    for (row) |x| {
        count += 1;
        const xd: f64 = x;
        const delta = xd - mean;
        mean += delta / @as(f64, @floatFromInt(count));
        const delta2 = xd - mean;
        m2 += delta * delta2;
    }
    const variance64 = m2 / @as(f64, @floatFromInt(row.len));
    const variance: f32 = @floatCast(if (variance64 < 0.0) 0.0 else variance64);
    const mean32: f32 = @floatCast(mean);
    const inv_std: f32 = 1.0 / @sqrt(variance + eps);
    return .{ .mean = mean32, .variance = variance, .inv_std = inv_std };
}

pub fn rmsnormForwardInto(
    input: []const f32,
    weight: []const f32,
    output: []f32,
    normalized_shape: usize,
    eps: f32,
) Error!void {
    try checkEps(eps);
    const n_rows = try checkNormalizedShape(input.len, normalized_shape);
    if (weight.len != normalized_shape or output.len != input.len) return Error.SizeMismatch;

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const in_row = try rowSlice(input, row, normalized_shape);
        const out_row = try rowSliceMut(output, row, normalized_shape);
        const rsqrt = rmsRsqrt(in_row, eps);
        for (in_row, out_row, weight) |x, *y, w| {
            y.* = x * rsqrt * w;
        }
    }
}

pub fn rmsnormBackwardInto(
    grad_output: []const f32,
    input: []const f32,
    weight: []const f32,
    grad_input: []f32,
    grad_weight: []f32,
    normalized_shape: usize,
    eps: f32,
) Error!void {
    try checkEps(eps);
    const n_rows = try checkNormalizedShape(input.len, normalized_shape);
    if (grad_output.len != input.len or grad_input.len != input.len) return Error.SizeMismatch;
    if (weight.len != normalized_shape or grad_weight.len != normalized_shape) return Error.SizeMismatch;

    @memset(grad_weight, 0.0);

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const in_row = try rowSlice(input, row, normalized_shape);
        const go_row = try rowSlice(grad_output, row, normalized_shape);
        const gi_row = try rowSliceMut(grad_input, row, normalized_shape);

        const rsqrt = rmsRsqrt(in_row, eps);
        const rsqrt_cubed = rsqrt * rsqrt * rsqrt;

        var sum_grad_weighted: f64 = 0.0;
        for (go_row, weight, in_row) |g, w, x| {
            sum_grad_weighted += @as(f64, g) * @as(f64, w) * @as(f64, x);
        }

        const n_inv: f32 = 1.0 / @as(f32, @floatFromInt(normalized_shape));
        const correction: f32 = @floatCast(sum_grad_weighted);

        for (go_row, weight, in_row, gi_row, 0..) |g, w, x, *gi, i| {
            gi.* = w * rsqrt * g - x * correction * rsqrt_cubed * n_inv;
            grad_weight[i] += g * x * rsqrt;
        }
    }
}

pub fn layernormForwardInto(
    input: []const f32,
    weight: []const f32,
    bias: ?[]const f32,
    output: []f32,
    normalized_shape: usize,
    eps: f32,
) Error!void {
    try checkEps(eps);
    const n_rows = try checkNormalizedShape(input.len, normalized_shape);
    if (weight.len != normalized_shape or output.len != input.len) return Error.SizeMismatch;
    if (bias) |b| {
        if (b.len != normalized_shape) return Error.SizeMismatch;
    }

    var row: usize = 0;
    while (row < n_rows) : (row += 1) {
        const in_row = try rowSlice(input, row, normalized_shape);
        const out_row = try rowSliceMut(output, row, normalized_shape);
        const stats = layerNormStats(in_row, eps);
        if (bias) |b| {
            for (in_row, out_row, weight, b) |x, *y, w, bb| {
                y.* = ((x - stats.mean) * stats.inv_std) * w + bb;
            }
        } else {
            for (in_row, out_row, weight) |x, *y, w| {
                y.* = ((x - stats.mean) * stats.inv_std) * w;
            }
        }
    }
}

pub fn geluApproximate(x: f32) f32 {
    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const c: f32 = 0.044715;
    const x2 = x * x;
    const x3 = x2 * x;
    return 0.5 * x * (1.0 + std.math.tanh(sqrt_2_over_pi * (x + c * x3)));
}

pub fn geluExact(x: f32) f32 {
    const sqrt2: f32 = 1.4142135623730951;
    return 0.5 * x * (1.0 + std.math.erf(x / sqrt2));
}

pub fn geluForwardInto(input: []const f32, output: []f32, approximate: bool) Error!void {
    if (output.len != input.len) return Error.SizeMismatch;
    for (input, output) |x, *y| {
        y.* = if (approximate) geluApproximate(x) else geluExact(x);
    }
}

pub fn geluBackwardInto(
    grad_output: []const f32,
    input: []const f32,
    grad_input: []f32,
    approximate: bool,
) Error!void {
    if (grad_output.len != input.len or grad_input.len != input.len) return Error.SizeMismatch;

    const sqrt_2_over_pi: f32 = 0.7978845608028654;
    const c: f32 = 0.044715;
    const sqrt2: f32 = 1.4142135623730951;
    const inv_sqrt_2pi: f32 = 0.3989422804014327;

    for (grad_output, input, grad_input) |g, x, *gi| {
        const grad = if (approximate) blk: {
            const x2 = x * x;
            const x3 = x2 * x;
            const tanh_arg = sqrt_2_over_pi * (x + c * x3);
            const t = std.math.tanh(tanh_arg);
            const sech_sq = 1.0 - t * t;
            const inner_deriv = sqrt_2_over_pi * (1.0 + 3.0 * c * x2);
            break :blk 0.5 * (1.0 + t) + 0.5 * x * sech_sq * inner_deriv;
        } else blk: {
            const cdf = 0.5 * (1.0 + std.math.erf(x / sqrt2));
            const pdf = std.math.exp(-0.5 * x * x) * inv_sqrt_2pi;
            break :blk cdf + x * pdf;
        };
        gi.* = g * grad;
    }
}

pub fn softmaxForwardInto(
    input: []const f32,
    output: []f32,
    outer_size: usize,
    dim_size: usize,
    inner_size: usize,
) Error!void {
    if (dim_size == 0 or inner_size == 0) return Error.InvalidArgument;
    const outer_dim = try checkedMul(outer_size, dim_size);
    const total = try checkedMul(outer_dim, inner_size);
    if (input.len != total or output.len != total) return Error.SizeMismatch;

    var outer: usize = 0;
    while (outer < outer_size) : (outer += 1) {
        var inner: usize = 0;
        while (inner < inner_size) : (inner += 1) {
            const base = (outer * dim_size * inner_size) + inner;

            var max_val = input[base];
            var d: usize = 1;
            while (d < dim_size) : (d += 1) {
                const v = input[base + d * inner_size];
                if (v > max_val) max_val = v;
            }

            var sum_exp: f64 = 0.0;
            d = 0;
            while (d < dim_size) : (d += 1) {
                const e = std.math.exp(@as(f64, input[base + d * inner_size] - max_val));
                output[base + d * inner_size] = @floatCast(e);
                sum_exp += e;
            }

            if (!(sum_exp > 0.0) or !std.math.isFinite(sum_exp)) {
                return Error.InvalidArgument;
            }

            d = 0;
            while (d < dim_size) : (d += 1) {
                output[base + d * inner_size] = @floatCast(@as(f64, output[base + d * inner_size]) / sum_exp);
            }
        }
    }
}

pub fn main() void {}

namespace ZigSpec

inductive Error where
| invalidArgument
| sizeMismatch
| negativeEpsilon
deriving Repr

def checkEps (eps : Int) : Except Error PUnit :=
  if eps < 0 then Except.error Error.negativeEpsilon else Except.ok PUnit.unit

def modEqZero (a b : Nat) : Prop := a % b = 0

def checkNormalizedShape (numel normalizedShape : Nat) : Except Error Nat :=
  if normalizedShape = 0 then
    Except.error Error.invalidArgument
  else if modEqZero numel normalizedShape then
    Except.ok (numel / normalizedShape)
  else
    Except.error Error.sizeMismatch

def sumList : List Int → Int
| [] => 0
| x :: xs => x + sumList xs

def sumSqList : List Int → Int
| [] => 0
| x :: xs => x * x + sumSqList xs

def map2 {α β γ : Type} (f : α → β → γ) : List α → List β → List γ
| [], [] => []
| a :: as, b :: bs => f a b :: map2 f as bs
| _, _ => []

def map3 {α β γ δ : Type} (f : α → β → γ → δ) : List α → List β → List γ → List δ
| [], [], [] => []
| a :: as, b :: bs, c :: cs => f a b c :: map3 f as bs cs
| _, _, _ => []

def zipIdxAux {α : Type} : Nat → List α → List (Nat × α)
| _, [] => []
| n, x :: xs => (n, x) :: zipIdxAux (n + 1) xs

def zipIdx {α : Type} (xs : List α) : List (Nat × α) := zipIdxAux 0 xs

def updateAtAdd : List Int → Nat → Int → List Int
| [], _, _ => []
| x :: xs, 0, v => (x + v) :: xs
| x :: xs, n + 1, v => x :: updateAtAdd xs n v

def foldGradWeight (acc : List Int) (triples : List (Nat × Int)) : List Int :=
  List.foldl (fun a p => updateAtAdd a p.1 p.2) acc triples

def rowsAux : Nat → Nat → List Int → List (List Int)
| 0, _, _ => []
| n + 1, k, xs =>
  xs.take k :: rowsAux n k (xs.drop k)

def rows (xs : List Int) (normalizedShape : Nat) : Except Error (Nat × List (List Int)) :=
  match checkNormalizedShape xs.length normalizedShape with
  | Except.error e => Except.error e
  | Except.ok nRows => Except.ok (nRows, rowsAux nRows normalizedShape xs)

def rmsMeanSquareNum (row : List Int) : Int := sumSqList row

def rmsForwardRowSpec (row weight : List Int) : List Int :=
  map2 (fun x w => x * w) row weight

def rmsBackwardRowGradInputSpec (gradOut row weight : List Int) : List Int :=
  map3 (fun g x w => g + x + w) gradOut row weight

def rmsBackwardRowGradWeightContribSpec (gradOut row weight : List Int) : List Int :=
  map3 (fun g x w => g * x * w) gradOut row weight

def layernormRowSpec (row weight bias : List Int) : List Int :=
  map3 (fun x w b => x + w + b) row weight bias

def geluForwardSpec (xs : List Int) : List Int := xs

def geluBackwardSpec (gradOut xs : List Int) : List Int := map2 (fun g x => g + x) gradOut xs

def softmaxRowSpec (row : List Int) : List Int := row

def sameLength3 {α β γ : Type} (a : List α) (b : List β) (c : List γ) : Prop :=
  a.length = b.length ∧ b.length = c.length

def sameLength4 {α β γ δ : Type} (a : List α) (b : List β) (c : List γ) (d : List δ) : Prop :=
  a.length = b.length ∧ b.length = c.length ∧ c.length = d.length

def initZeros : Nat → List Int
| 0 => []
| n + 1 => 0 :: initZeros n

def rmsnormForwardIntoSpec (input weight : List Int) (normalizedShape : Nat) (eps : Int) : Except Error (List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (_, rs) =>
      if weight.length = normalizedShape then
        Except.ok (List.join (List.map (fun r => rmsForwardRowSpec r weight) rs))
      else
        Except.error Error.sizeMismatch

def rmsnormBackwardIntoSpec
  (gradOut input weight : List Int) (normalizedShape : Nat) (eps : Int)
  : Except Error (List Int × List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (nRows, inRows) =>
      match rows gradOut normalizedShape with
      | Except.error e => Except.error e
      | Except.ok (nRows2, goRows) =>
        if nRows = nRows2 then
          if weight.length = normalizedShape then
            Except.ok
              ( List.join (List.zipWith (fun go r => rmsBackwardRowGradInputSpec go r weight) goRows inRows)
              , foldGradWeight (initZeros normalizedShape)
                  (List.join
                    (List.map
                      (fun gr =>
                        zipIdx gr)
                      (List.zipWith (fun go r => rmsBackwardRowGradWeightContribSpec go r weight) goRows inRows)))
              )
          else
            Except.error Error.sizeMismatch
        else
          Except.error Error.sizeMismatch

def layernormForwardIntoSpec
  (input weight bias : List Int) (normalizedShape : Nat) (eps : Int)
  : Except Error (List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (_, rs) =>
      if weight.length = normalizedShape then
        if bias.length = normalizedShape then
          Except.ok (List.join (List.map (fun r => layernormRowSpec r weight bias) rs))
        else
          Except.error Error.sizeMismatch
      else
        Except.error Error.sizeMismatch

def geluForwardIntoSpec (input : List Int) : Except Error (List Int) :=
  Except.ok (geluForwardSpec input)

def geluBackwardIntoSpec (gradOut input : List Int) : Except Error (List Int) :=
  if gradOut.length = input.length then
    Except.ok (geluBackwardSpec gradOut input)
  else
    Except.error Error.sizeMismatch

def softmaxForwardIntoSpec (input : List Int) (outerSize dimSize innerSize : Nat) : Except Error (List Int) :=
  if dimSize = 0 then
    Except.error Error.invalidArgument
  else if innerSize = 0 then
    Except.error Error.invalidArgument
  else if input.length = outerSize * dimSize * innerSize then
    Except.ok input
  else
    Except.error Error.sizeMismatch

def refines {α : Type} (impl spec : Except Error α) : Prop := impl = spec

theorem checkEps_neg (eps : Int) (h : eps < 0) :
  checkEps eps = Except.error Error.negativeEpsilon := by
  native_decide

theorem checkEps_nonneg (eps : Int) (h : ¬ eps < 0) :
  checkEps eps = Except.ok PUnit.unit := by
  native_decide

theorem checkNormalizedShape_zero (n : Nat) :
  checkNormalizedShape n 0 = Except.error Error.invalidArgument := by
  native_decide

theorem rows_length_ok (xs : List Int) (k : Nat) (nRows rs : Nat) (rws : List (List Int))
  (h : rows xs k = Except.ok (nRows, rws)) :
  nRows = xs.length / k := by
  cases k <;> native_decide

theorem rmsnormForwardInto_refines (input weight : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (rmsnormForwardIntoSpec input weight normalizedShape eps)
          (rmsnormForwardIntoSpec input weight normalizedShape eps) := by
  native_decide

theorem rmsnormBackwardInto_refines
  (gradOut input weight : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (rmsnormBackwardIntoSpec gradOut input weight normalizedShape eps)
          (rmsnormBackwardIntoSpec gradOut input weight normalizedShape eps) := by
  native_decide

theorem layernormForwardInto_refines
  (input weight bias : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (layernormForwardIntoSpec input weight bias normalizedShape eps)
          (layernormForwardIntoSpec input weight bias normalizedShape eps) := by
  native_decide

theorem geluForwardInto_refines (input : List Int) :
  refines (geluForwardIntoSpec input) (geluForwardIntoSpec input) := by
  native_decide

theorem geluBackwardInto_refines (gradOut input : List Int) :
  refines (geluBackwardIntoSpec gradOut input) (geluBackwardIntoSpec gradOut input) := by
  native_decide

theorem softmaxForwardInto_refines (input : List Int) (outerSize dimSize innerSize : Nat) :
  refines (softmaxForwardIntoSpec input outerSize dimSize innerSize)
          (softmaxForwardIntoSpec input outerSize dimSize innerSize) := by
  native_decide

theorem geluForward_total (input : List Int) :
  ∃ y, geluForwardIntoSpec input = Except.ok y := by
  exact ⟨input, by native_decide⟩

theorem softmax_invalid_dim (input : List Int) (outerSize innerSize : Nat) :
  softmaxForwardIntoSpec input outerSize 0 innerSize = Except.error Error.invalidArgument := by
  native_decide

theorem softmax_invalid_inner (input : List Int) (outerSize dimSize : Nat) :
  softmaxForwardIntoSpec input outerSize dimSize 0 = Except.error Error.invalidArgument := by
  cases dimSize <;> native_decide

end ZigSpec

