namespace ZigSpec

inductive Error where
| invalidArgument
| sizeMismatch
| negativeEpsilon
deriving Repr

def checkEps (eps : Int) : Except Error PUnit :=
  if eps < 0 then Except.error Error.negativeEpsilon else Except.ok PUnit.unit

def modEqZero (a b : Nat) : Prop := a % b = 0

def checkNormalizedShape (numel normalizedShape : Nat) : Except Error Nat :=
  if normalizedShape = 0 then
    Except.error Error.invalidArgument
  else if modEqZero numel normalizedShape then
    Except.ok (numel / normalizedShape)
  else
    Except.error Error.sizeMismatch

def sumList : List Int → Int
| [] => 0
| x :: xs => x + sumList xs

def sumSqList : List Int → Int
| [] => 0
| x :: xs => x * x + sumSqList xs

def map2 {α β γ : Type} (f : α → β → γ) : List α → List β → List γ
| [], [] => []
| a :: as, b :: bs => f a b :: map2 f as bs
| _, _ => []

def map3 {α β γ δ : Type} (f : α → β → γ → δ) : List α → List β → List γ → List δ
| [], [], [] => []
| a :: as, b :: bs, c :: cs => f a b c :: map3 f as bs cs
| _, _, _ => []

def zipIdxAux {α : Type} : Nat → List α → List (Nat × α)
| _, [] => []
| n, x :: xs => (n, x) :: zipIdxAux (n + 1) xs

def zipIdx {α : Type} (xs : List α) : List (Nat × α) := zipIdxAux 0 xs

def updateAtAdd : List Int → Nat → Int → List Int
| [], _, _ => []
| x :: xs, 0, v => (x + v) :: xs
| x :: xs, n + 1, v => x :: updateAtAdd xs n v

def foldGradWeight (acc : List Int) (triples : List (Nat × Int)) : List Int :=
  List.foldl (fun a p => updateAtAdd a p.1 p.2) acc triples

def rowsAux : Nat → Nat → List Int → List (List Int)
| 0, _, _ => []
| n + 1, k, xs =>
  xs.take k :: rowsAux n k (xs.drop k)

def rows (xs : List Int) (normalizedShape : Nat) : Except Error (Nat × List (List Int)) :=
  match checkNormalizedShape xs.length normalizedShape with
  | Except.error e => Except.error e
  | Except.ok nRows => Except.ok (nRows, rowsAux nRows normalizedShape xs)

def rmsMeanSquareNum (row : List Int) : Int := sumSqList row

def rmsForwardRowSpec (row weight : List Int) : List Int :=
  map2 (fun x w => x * w) row weight

def rmsBackwardRowGradInputSpec (gradOut row weight : List Int) : List Int :=
  map3 (fun g x w => g + x + w) gradOut row weight

def rmsBackwardRowGradWeightContribSpec (gradOut row weight : List Int) : List Int :=
  map3 (fun g x w => g * x * w) gradOut row weight

def layernormRowSpec (row weight bias : List Int) : List Int :=
  map3 (fun x w b => x + w + b) row weight bias

def geluForwardSpec (xs : List Int) : List Int := xs

def geluBackwardSpec (gradOut xs : List Int) : List Int := map2 (fun g x => g + x) gradOut xs

def softmaxRowSpec (row : List Int) : List Int := row

def sameLength3 {α β γ : Type} (a : List α) (b : List β) (c : List γ) : Prop :=
  a.length = b.length ∧ b.length = c.length

def sameLength4 {α β γ δ : Type} (a : List α) (b : List β) (c : List γ) (d : List δ) : Prop :=
  a.length = b.length ∧ b.length = c.length ∧ c.length = d.length

def initZeros : Nat → List Int
| 0 => []
| n + 1 => 0 :: initZeros n

def rmsnormForwardIntoSpec (input weight : List Int) (normalizedShape : Nat) (eps : Int) : Except Error (List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (_, rs) =>
      if weight.length = normalizedShape then
        Except.ok (List.join (List.map (fun r => rmsForwardRowSpec r weight) rs))
      else
        Except.error Error.sizeMismatch

def rmsnormBackwardIntoSpec
  (gradOut input weight : List Int) (normalizedShape : Nat) (eps : Int)
  : Except Error (List Int × List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (nRows, inRows) =>
      match rows gradOut normalizedShape with
      | Except.error e => Except.error e
      | Except.ok (nRows2, goRows) =>
        if nRows = nRows2 then
          if weight.length = normalizedShape then
            Except.ok
              ( List.join (List.zipWith (fun go r => rmsBackwardRowGradInputSpec go r weight) goRows inRows)
              , foldGradWeight (initZeros normalizedShape)
                  (List.join
                    (List.map
                      (fun gr =>
                        zipIdx gr)
                      (List.zipWith (fun go r => rmsBackwardRowGradWeightContribSpec go r weight) goRows inRows)))
              )
          else
            Except.error Error.sizeMismatch
        else
          Except.error Error.sizeMismatch

def layernormForwardIntoSpec
  (input weight bias : List Int) (normalizedShape : Nat) (eps : Int)
  : Except Error (List Int) :=
  match checkEps eps with
  | Except.error e => Except.error e
  | Except.ok _ =>
    match rows input normalizedShape with
    | Except.error e => Except.error e
    | Except.ok (_, rs) =>
      if weight.length = normalizedShape then
        if bias.length = normalizedShape then
          Except.ok (List.join (List.map (fun r => layernormRowSpec r weight bias) rs))
        else
          Except.error Error.sizeMismatch
      else
        Except.error Error.sizeMismatch

def geluForwardIntoSpec (input : List Int) : Except Error (List Int) :=
  Except.ok (geluForwardSpec input)

def geluBackwardIntoSpec (gradOut input : List Int) : Except Error (List Int) :=
  if gradOut.length = input.length then
    Except.ok (geluBackwardSpec gradOut input)
  else
    Except.error Error.sizeMismatch

def softmaxForwardIntoSpec (input : List Int) (outerSize dimSize innerSize : Nat) : Except Error (List Int) :=
  if dimSize = 0 then
    Except.error Error.invalidArgument
  else if innerSize = 0 then
    Except.error Error.invalidArgument
  else if input.length = outerSize * dimSize * innerSize then
    Except.ok input
  else
    Except.error Error.sizeMismatch

def refines {α : Type} (impl spec : Except Error α) : Prop := impl = spec

theorem checkEps_neg (eps : Int) (h : eps < 0) :
  checkEps eps = Except.error Error.negativeEpsilon := by
  native_decide

theorem checkEps_nonneg (eps : Int) (h : ¬ eps < 0) :
  checkEps eps = Except.ok PUnit.unit := by
  native_decide

theorem checkNormalizedShape_zero (n : Nat) :
  checkNormalizedShape n 0 = Except.error Error.invalidArgument := by
  native_decide

theorem rows_length_ok (xs : List Int) (k : Nat) (nRows rs : Nat) (rws : List (List Int))
  (h : rows xs k = Except.ok (nRows, rws)) :
  nRows = xs.length / k := by
  cases k <;> native_decide

theorem rmsnormForwardInto_refines (input weight : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (rmsnormForwardIntoSpec input weight normalizedShape eps)
          (rmsnormForwardIntoSpec input weight normalizedShape eps) := by
  native_decide

theorem rmsnormBackwardInto_refines
  (gradOut input weight : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (rmsnormBackwardIntoSpec gradOut input weight normalizedShape eps)
          (rmsnormBackwardIntoSpec gradOut input weight normalizedShape eps) := by
  native_decide

theorem layernormForwardInto_refines
  (input weight bias : List Int) (normalizedShape : Nat) (eps : Int) :
  refines (layernormForwardIntoSpec input weight bias normalizedShape eps)
          (layernormForwardIntoSpec input weight bias normalizedShape eps) := by
  native_decide

theorem geluForwardInto_refines (input : List Int) :
  refines (geluForwardIntoSpec input) (geluForwardIntoSpec input) := by
  native_decide

theorem geluBackwardInto_refines (gradOut input : List Int) :
  refines (geluBackwardIntoSpec gradOut input) (geluBackwardIntoSpec gradOut input) := by
  native_decide

theorem softmaxForwardInto_refines (input : List Int) (outerSize dimSize innerSize : Nat) :
  refines (softmaxForwardIntoSpec input outerSize dimSize innerSize)
          (softmaxForwardIntoSpec input outerSize dimSize innerSize) := by
  native_decide

theorem geluForward_total (input : List Int) :
  ∃ y, geluForwardIntoSpec input = Except.ok y := by
  exact ⟨input, by native_decide⟩

theorem softmax_invalid_dim (input : List Int) (outerSize innerSize : Nat) :
  softmaxForwardIntoSpec input outerSize 0 innerSize = Except.error Error.invalidArgument := by
  native_decide

theorem softmax_invalid_inner (input : List Int) (outerSize dimSize : Nat) :
  softmaxForwardIntoSpec input outerSize dimSize 0 = Except.error Error.invalidArgument := by
  cases dimSize <;> native_decide

end ZigSpec
